import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.PrintWriter;import java.util.StringTokenizer;import java.io.IOException;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);String line = br.readLine();if (line != null) {int t = Integer.parseInt(line.trim());while (t-- > 0) {String xStr = br.readLine();if (xStr != null) {int x = Integer.parseInt(xStr.trim());out.println(x * 10);}}}out.flush();out.close();}}